def read_account(account_id: int, request: Request):
    account = current(request)
    conn = request.app.state.conn
    row = conn.execute(
        "SELECT * FROM accounts WHERE id = ?",
        (account_id,),
    ).fetchone()
    if row is None:
        fail(404, "not found")
    return account_json(row, include_recovery=int(account["id"]) == int(row["id"]))

def device_notes_for(conn, caller_id, device_id):
    if not may_view_device(conn, caller_id, device_id):
        return None
    return conn.execute(
        """
        SELECT * FROM device_notes
        WHERE device_id = ? AND author_account_id = ?
        ORDER BY id
        """,
        (device_id, caller_id),
    ).fetchall()

def update_device(device_id: int, body: DeviceUpdate, request: Request):
    account = current(request)
    label = body.label.strip()
    if not label:
        fail(400, "invalid device")
    conn = request.app.state.conn
    row = conn.execute(
        "SELECT * FROM devices WHERE id = ?",
        (device_id,),
    ).fetchone()
    if row is None:
        fail(404, "not found")
    if int(row["owner_account_id"]) != int(account["id"]):
        fail(403, "forbidden")
    conn.execute(
        "UPDATE devices SET label = ? WHERE id = ?",
        (label, device_id),
    )
    conn.commit()
    updated = conn.execute(
        "SELECT * FROM devices WHERE id = ?",
        (device_id,),
    ).fetchone()
    return device_json(updated)

def read_note(note_id: int, request: Request):
    account = current(request)
    conn = request.app.state.conn
    row = conn.execute(
        "SELECT * FROM notes WHERE id = ?",
        (note_id,),
    ).fetchone()
    if row is None:
        fail(404, "not found")
    if not access.may_read_account(conn, account["id"], row["account_id"]):
        fail(403, "forbidden")
    return note_json(row)

def account_for_token(conn, token):
    row = conn.execute(
        "SELECT account_id FROM sessions WHERE token = ?",
        (token,),
    ).fetchone()
    if row is None:
        return None
    account = conn.execute(
        "SELECT * FROM accounts WHERE id = ?",
        (row["account_id"],),
    ).fetchone()
    if account is None:
        return None
    if account["status"] != "active" or account["merged_into_id"] is not None:
        return None
    return account
